// v16.xx (chips1), HIS RULE (2026-10-14), "integrated and polished like the previous stuff": THE POWER-UP CHIP IS A HUD PLATE. It was its own
// flat dark box with a rail, drawn by hand, in the smallest type; it is the line plate now (rounded, the 3 px rail in its power-up colour),
// the name and the seconds in the label size like the feed lines, and the timer bar under the words. A chip blinks over its last 3 s as before.
c.globalAlpha=a; hudPlate(x0,y0,Math.round(ew),Math.round(28*z),'rgba('+D.rgb+',1)',HUDC.plate);
c.fillStyle='rgba('+D.rgb+',.9)'; c.fillRect(x0+Math.round(8*z),y0+Math.round(24*z),Math.round((ew-14*z)*f),Math.round(2.5*z));
c.fillStyle=HUDC.text; hudText(D.n,x0+Math.round(11*z),y0+Math.round(18*z));
c.textAlign='right'; c.fillStyle='rgba('+D.rgb+',1)'; hudText(Math.ceil(S.act[D.k])+'S',x0+Math.round(ew-8*z),y0+Math.round(18*z)); c.textAlign='left';

