{v:'VER',what:'the HUD rule: a power-up chip is a HUD line plate with its name and seconds in the HUD label size, not the old flat box in the smallest type',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__textTrace||typeof pwrDraw!=='function') return 'SKIP: no raid or power-ups here';
   var bad=[], g, p, tr, ref, nm, ch, oHP=hudPlate, plates=0, i, D;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     try{ careerPostBuild(g); }catch(_c){}
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={}; p=g.player; p.iv=99;
     D=PWR_KINDS[0]; nm=D.n;
     pwrS().act[D.k]=12;
     hudPlate=function(){ plates++; return oHP.apply(this,arguments); };
     try{
       ctx.save();
       tr=__textTrace(function(){ ctx.font=hudFS(TYPE.label); ctx.fillStyle='#fff'; ctx.fillText('REFLABEL',5,5); pwrDraw(ctx,p); });
       ctx.restore();
     } finally { hudPlate=oHP; }
     ref=tr.filter(function(t){ return t.t==='REFLABEL'; })[0];
     ch=tr.filter(function(t){ return t.t===nm; })[0];
     if(!ch) return 'SKIP: the power-up chip was not drawn';
     if(plates<1) bad.push('the chip is not drawn on a HUD plate');
     if(ref&&ch.px<ref.px*0.95) bad.push('the chip name is '+ch.px.toFixed(1)+' px against the HUD label size '+ref.px.toFixed(1));
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ hudPlate=oHP; }catch(_h){} try{ var g2=__state(); if(g2&&!g2.over){ g2.career=0; g2.player.iv=0; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
